INSERT INTO products (id,name,category,price,promo,farm,lot,weight,ingredients,expiry,storage,certs,story,shop,photo,verified) VALUES ('bot-ca-cao-nguyen-chat-trong-duc', 'Bột Ca cao nguyên chất Trọng Đức', 'Ca cao & Cà phê', 145000, 'OCOP 4 sao · Bán chạy nhất', 'Công ty TNHH Ca cao Trọng Đức, Định Quán, Đồng Nai', 'CDQ-2026', 'Hộp 400g (20 gói x 20g)', '100% hạt ca cao lên men tự nhiên Đồng Nai', '18 tháng kể từ ngày sản xuất', 'Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp', '4 sao', 'Vùng trồng ca cao Định Quán được phù sa sông Đồng Nai bồi đắp, kết hợp quy trình ủ lên men tự nhiên theo tiêu chuẩn xuất khẩu Nhật Bản, mang lại hương vị thơm nồng, đậm đà khó quên.', 'https://cacaotrongduc.com.vn', '/bot-cacao-3in1.jpg', TRUE)
INSERT INTO diary_entries (id,product_id,stage,text,photo,ts) VALUES ('ent-1', 'bot-ca-cao-nguyen-chat-trong-duc', 'Thu hoạch', 'Thu hái trái ca cao chín vàng tại vườn xã Phú Hòa, Định Quán. Trái được chọn lọc kỹ càng, đồng đều kích cỡ.', '/bot-cacao-3in1.jpg', NOW() - INTERVAL '14 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id,product_id,stage,text,photo,ts) VALUES ('ent-2', 'bot-ca-cao-nguyen-chat-trong-duc', 'Sơ chế', 'Tách hạt và ủ lên men tự nhiên trong thùng gỗ sồi 6 ngày đêm, đảo hạt đều đặn để phát triển hương thơm sô-cô-la đặc trưng.', NULL, NOW() - INTERVAL '7 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id,product_id,stage,text,photo,ts) VALUES ('ent-3', 'bot-ca-cao-nguyen-chat-trong-duc', 'Đóng gói', 'Nghiền mịn, kiểm tra an toàn vệ sinh thực phẩm và đóng hộp thiếc kín khí kèm tem Hộ chiếu số OCOP.', NULL, NOW() - INTERVAL '2 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id,name,category,price,promo,farm,lot,weight,ingredients,expiry,storage,certs,story,shop,photo,verified) VALUES ('hat-dieu-rang-muoi-dinh-quan', 'Hạt điều vỏ lụa rang muối Định Quán', 'Hạt & Trái cây', 185000, 'OCOP 4 sao · Giòn bùi thơm ngon', 'HTX Nông nghiệp Tân Phú - Định Quán, Đồng Nai', 'HDQ-882', 'Hũ 500g', 'Hạt điều loại A nguyên hạt (99%), muối tinh khiết (1%)', '12 tháng kể từ ngày sản xuất', 'Đậy kín sau khi mở, để nơi khô ráo thoáng mát', '4 sao', 'Hạt điều Đồng Nai nổi tiếng với độ giòn rụm, vị ngọt bùi tự nhiên. Được rang củi thủ công giữ trọn lớp vỏ lụa bảo vệ hạt thơm lừng.', NULL, NULL, TRUE)
INSERT INTO diary_entries (id,product_id,stage,text,photo,ts) VALUES ('ent-hd-1', 'hat-dieu-rang-muoi-dinh-quan', 'Thu hoạch', 'Thu hoạch hạt điều chín rộ vụ xuân tại vùng đất bazan màu mỡ Định Quán.', NULL, NOW() - INTERVAL '10 days') ON CONFLICT (id) DO NOTHING;
