INSERT INTO products (id,name,category,price,promo,farm,lot,weight,ingredients,expiry,storage,certs,story,shop,photo,verified) VALUES ('mat-ong-hoa-tram-rung-tri-an', 'Mật ong hoa tràm tự nhiên Rừng Trị An', 'Mật ong & Đặc sản', 220000, 'OCOP 4 sao · Thuần khiết thiên nhiên', 'Khu bảo tồn thiên nhiên văn hóa Đồng Nai, Vĩnh Cửu', 'MTA-520', 'Chai 500ml', '100% mật ong hoa tràm tự nhiên nguyên chất', '24 tháng kể từ ngày thu hoạch', 'Nhiệt độ phòng thoáng mát, không bảo quản trong tủ lạnh', '4 sao', 'Mật ong thu hái từ rừng tràm nguyên sinh ven hồ Trị An, màu vàng óng sóng sánh, thơm nhẹ mùi hoa tràm.', NULL, NULL, TRUE)
