INSERT INTO products (id,name,category,price,promo,farm,lot,weight,ingredients,expiry,storage,certs,story,shop,photo,verified) VALUES ('ca-phe-robusta-long-khanh', 'Cà phê Robusta mộc Long Khánh', 'Ca cao & Cà phê', 160000, 'OCOP 3 sao · Đậm vị truyền thống', 'Nông trường Cà phê Long Khánh, Đồng Nai', 'CLK-109', 'Túi 500g', '100% hạt Robusta chín cây hái chọn lọc', '12 tháng kể từ ngày rang', 'Bảo quản nơi khô ráo, tránh không khí và ánh nắng', '3 sao', 'Được trồng trên sườn đồi thoai thoải Long Khánh với biên độ nhiệt ngày đêm lý tưởng, cho hạt cà phê đậm đà thể chất, hậu vị đầm sâu đặc trưng phương Nam.', NULL, NULL, TRUE)
INSERT INTO products (id,name,category,price,promo,farm,lot,weight,ingredients,expiry,storage,certs,story,shop,photo,verified) VALUES ('buoi-tan-trieu-vinh-cuu', 'Bưởi da xanh Tân Triều', 'Hạt & Trái cây', 95000, 'Đặc sản Tân Triều · Múi mọng ngọt thanh', 'HTX Bưởi Tân Triều, Vĩnh Cửu, Đồng Nai', 'BTT-301', 'Thùng 5kg (2-3 trái)', '100% bưởi tươi trồng tại Tân Triều', '15 ngày kể từ ngày thu hoạch', 'Nơi thoáng mát, tránh ánh nắng; có thể để ngăn mát tủ lạnh', 'Đang chờ đánh giá OCOP', 'Cù lao Tân Triều bên dòng sông Đồng Nai có đất phù sa màu mỡ, nơi nhiều thế hệ nhà vườn giữ nghề trồng bưởi. Trái được tỉa cành, bao trái và thu hái bằng tay.', NULL, NULL, FALSE)
